import{_ as a,b as i,e as t,a8 as r}from"./chunks/framework.CNHV3T2x.js";const f=JSON.parse('{"title":"Features","description":"","frontmatter":{"date":1787832829000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":1787832829000,"timestamp":1787832829000,"datetime":"2026-08-27T12:13:49.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),n={name:"guide/features.md"};function s(l,e,o,p,d,m){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>The features of Graphics32, while similar to those in the standard TImage, TBitmap, and TCanvas classes, far surpasses the capabilities of its VCL counterparts. Graphics32 has been written to accelerate and optimize drawing on 32-bit device-independent bitmaps (DIBs) independently from the Windows GDI.</p><p>Some of its features include:</p><ul><li>Fast per-pixel access up to 100 times faster compared to standard TCanvas/TBitmap.</li><li>High-performance bitmap alpha blending, including per-pixel alpha blending.</li><li>Pixel, line and polygon antialiasing with sub-pixel accuracy, combined with alpha blending.</li><li>Arbitrary polygon transformations and custom fillings.</li><li>Bitmap resampling with high quality reconstruction filters such as Lanczos, Cubic, and Mitchell.</li><li>A unique state-of-the-art rasterization system.</li><li>Affine transformations of bitmaps: rotations, scaling, etc with sub-pixel accuracy.</li><li>Arbitrary projective transformations of bitmaps.</li><li>Arbitrary remapping transformations of bitmaps. For example for Warping or Morphing.</li><li>Flexible supersampling implementation for maximum sampling quality.</li><li>Flicker-free image viewer controls with optimized double buffering via advanced MicroTiles based repaint optimizer.</li><li>Multiple customizable easy-to-use overlay layers.</li><li>Locking of bitmaps for safe multi-threading.</li><li>Platform independent code.</li><li>Switchable surface-managing back-ends.</li><li>A property editor for RGB and alpha channel loading.</li><li>A pluggable image format subsystem for import and export of arbitrary image formats.</li></ul><h6 id="see-also" tabindex="-1">See also: <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also:&quot;">​</a></h6><ul><li><a href="https://docs.microsoft.com/en-us/windows/win32/gdi/device-independent-bitmaps" target="_blank" rel="noreferrer">Device Independant Bitmaps (Microsoft)</a></li><li><a href="https://melander.dk/graphics32/repaint-optimization/" target="_blank" rel="noreferrer">Repaint Optimization</a></li><li><a href="https://melander.dk/graphics32/sampling-and-rasterization/" target="_blank" rel="noreferrer">Sampling and Rasterization</a></li></ul>',6)])])}const u=a(n,[["render",s]]);export{f as __pageData,u as default};
